<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'Access Data Exporter' }}</title><style>body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#172033}.wrap{max-width:1200px;margin:35px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px #00000008}h1{margin-top:0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:8px;border-bottom:1px solid #eee;text-align:left;white-space:nowrap}.table-wrap{overflow:auto}a{color:#2563eb;text-decoration:none}.btn{background:#2563eb;color:white;border:0;border-radius:8px;padding:9px 14px;cursor:pointer}.btn.gray{background:#64748b}input,select{padding:9px;border:1px solid #cbd5e1;border-radius:8px;width:100%;box-sizing:border-box}.row{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;align-items:end}.err{background:#fee2e2;color:#991b1b;padding:12px;border-radius:8px}</style></head><body><div class="wrap">@yield('content')</div></body></html>
